+    <script>
+        const questions = [
+            {
+                id: 1,
+                question: "1. Quelle est la dérivée de la fonction $f(x) = 3x^2 - 5x + 2$ ?",
+                options: [
+                    "A) $6x - 5$",
+                    "B) $3x - 5$",
+                    "C) $6x^2 - 5$",
+                    "D) $6x + 2$"
+                ],
+                correct: 0,
+                explanation: "Correction : La dérivée de $3x^2$ est $3 \\times 2x = 6x$, celle de $-5x$ est $-5$, et celle de la constante $2$ est $0$. Ainsi, $f'(x) = 6x - 5$."
+            },
+            {
+                id: 2,
+                question: "2. Quelle est la valeur de l'intégrale $\\int_{0}^{1} 2x \\, dx$ ?",
+                options: [
+                    "A) $0$",
+                    "B) $1$",
+                    "C) $2$",
+                    "D) $0.5$"
+                ],
+                correct: 1,
+                explanation: "Correction : Une primitive de $2x$ est $x^2$. En appliquant les bornes de $0$ à $1$, on obtient $1^2 - 0^2 = 1 - 0 = 1$."
+            },
+            {
+                id: 3,
+                question: "3. Soit une suite géométrique $(u_n)$ de premier terme $u_0 = 3$ et de raison $q = 2$. Quelle est la valeur de $u_3$ ?",
+                options: [
+                    "A) $12$",
+                    "B) $18$",
+                    "C) $24$",
+                    "D) $48$"
+                ],
+                correct: 2,
+                explanation: "Correction : Pour une suite géométrique, $u_n = u_0 \\times q^n$. Donc $u_3 = 3 \\times 2^3 = 3 \\times 8 = 24$."
+            },
+            {
+                id: 4,
+                question: "4. Quelle est la solution de l'équation $e^x = 5$ ?",
+                options: [
+                    "A) $x = 5$",
+                    "B) $x = \\ln(5) / e$",
+                    "C) $x = \\ln(5)$",
+                    "D) $x = 5e$"
+                ],
+                correct: 2,
+                explanation: "Correction : La fonction exponentielle et la fonction logarithme népérien ($\\ln$) sont réciproques. En appliquant $\\ln$ des deux côtés, on obtient $x = \\ln(5)$."
+            },
+            {
+                id: 5,
+                question: "5. Dans un triangle rectangle dont les côtés de l'angle droit mesurent $3\\text{ cm}$ et $4\\text{ cm}$, quelle est la longueur de l'hypoténuse ?",
+                options: [
+                    "A) $5\\text{ cm}$",
+                    "B) $6\\text{ cm}$",
+                    "C) $7\\text{ cm}$",
+                    "D) $25\\text{ cm}$"
+                ],
+                correct: 0,
+                explanation: "Correction : D'après le théorème de Pythagore, $c^2 = 3^2 + 4^2 = 9 + 16 = 25$. Donc $c = \\sqrt{25} = 5\\text{ cm}$."
+            }
+        ];
+
+        let userAnswers = {};
+
+        function renderQCM() {
+            const container = document.getElementById('qcmContainer');
+            container.innerHTML = '';
+
+            questions.forEach((q, index) => {
+                const card = document.createElement('div');
+                card.className = 'question-card';
+                card.id = `question-${q.id}`;
+
+                let optionsHtml = '';
+                q.options.forEach((opt, optIndex) => {
+                    optionsHtml += `<button class="option-btn" onclick="selectOption(${q.id}, ${optIndex})" id="q${q.id}-opt${optIndex}">${opt}</button>`;
+                });
+
+                card.innerHTML = `
+                    <div class="question-title">${q.question}</div>
+                    <div class="options-list" id="options-${q.id}">
+                        ${optionsHtml}
+                    </div>
+                    <div class="correction-box" id="correction-${q.id}">
+                        ${q.explanation}
+                    </div>
+                `;
+                container.appendChild(card);
+            });
+        }
+
+        function selectOption(questionId, optionIndex) {
+            if (userAnswers[questionId] !== undefined) return; // Empêcher de changer après réponse
+
+            userAnswers[questionId] = optionIndex;
+            const q = questions.find(item => item.id === questionId);
+
+            // Marquer les boutons
+            for (let i = 0; i < q.options.length; i++) {
+                const btn = document.getElementById(`q${questionId}-opt${i}`);
+                btn.disabled = true;
+                if (i === q.correct) {
+                    btn.classList.add('correct');
+                } else if (i === optionIndex) {
+                    btn.classList.add('incorrect');
+                }
+            }
+
+            // Afficher la correction
+            const correctionBox = document.getElementById(`correction-${questionId}`);
+            correctionBox.classList.add('show');
+            if (optionIndex === q.correct) {
+                correctionBox.classList.add('success');
+            } else {
+                correctionBox.classList.add('error');
+            }
+
+            // Vérifier si toutes les questions ont reçu une réponse
+            if (Object.keys(userAnswers).length === questions.length) {
+                showScore();
+            }
+        }
+
+        function showScore() {
+            let score = 0;
+            questions.forEach(q => {
+                if (userAnswers[q.id] === q.correct) {
+                    score++;
+                }
+            });
+
+            const scoreSection = document.getElementById('scoreSection');
+            const scoreText = document.getElementById('scoreText');
+            scoreText.innerHTML = `Vous avez obtenu <strong>${score} / ${questions.length}</strong> bonnes réponses.`;
+            scoreSection.style.display = 'block';
+            scoreSection.scrollIntoView({ behavior: 'smooth' });
+        }
+
+        function resetQCM() {
+            userAnswers = {};
+            document.getElementById('scoreSection').style.display = 'none';
+            renderQCM();
+            window.scrollTo({ top: 0, behavior: 'smooth' });
+        }
+
+        // Initialisation au chargement
+        window.addEventListener('DOMContentLoaded', renderQCM);
+    </script>
 </body>
 </html>

