    <script>
        const questions = [
            {
                id: 1,
                question: "1. Quelle est la dérivée de la fonction f(x) = 3x² - 5x + 2 ?",
                options: [
                    "A) 6x - 5",
                    "B) 3x - 5",
                    "C) 6x² - 5",
                    "D) 6x + 2"
                ],
                correct: 0,
                explanation: "Correction : La dérivée de 3x² est 3 × 2x = 6x, celle de -5x est -5, et celle de la constante 2 est 0. Ainsi, f'(x) = 6x - 5."
            },
            {
                id: 2,
                question: "2. Quelle est la valeur de l'intégrale de 0 à 1 de 2x dx ?",
                options: [
                    "A) 0",
                    "B) 1",
                    "C) 2",
                    "D) 0.5"
                ],
                correct: 1,
                explanation: "Correction : Une primitive de 2x est x². En appliquant les bornes de 0 à 1, on obtient 1² - 0² = 1 - 0 = 1."
            },
            {
                id: 3,
                question: "3. Soit une suite géométrique (un) de premier terme u0 = 3 et de raison q = 2. Quelle est la valeur de u3 ?",
                options: [
                    "A) 12",
                    "B) 18",
                    "C) 24",
                    "D) 48"
                ],
                correct: 2,
                explanation: "Correction : Pour une suite géométrique, u_n = u_0 × q^n. Donc u_3 = 3 × 2³ = 3 × 8 = 24."
            },
            {
                id: 4,
                question: "4. Quelle est la solution de l'équation e^x = 5 ?",
                options: [
                    "A) x = 5",
                    "B) x = ln(5) / e",
                    "C) x = ln(5)",
                    "D) x = 5e"
                ],
                correct: 2,
                explanation: "Correction : La fonction exponentielle et la fonction logarithme népérien (ln) sont réciproques. En appliquant ln des deux côtés, on obtient x = ln(5)."
            },
            {
                id: 5,
                question: "5. Dans un triangle rectangle dont les côtés de l'angle droit mesurent 3 cm et 4 cm, quelle est la longueur de l'hypoténuse ?",
                options: [
                    "A) 5 cm",
                    "B) 6 cm",
                    "C) 7 cm",
                    "D) 25 cm"
                ],
                correct: 0,
                explanation: "Correction : D'après le théorème de Pythagore, c² = 3² + 4² = 9 + 16 = 25. Donc c = √25 = 5 cm."
            }
        ];

        let userAnswers = {};

