            if (userAnswers[questionId] !== undefined) return;

            userAnswers[questionId] = optionIndex;
            const question = questions.find(q => q.id === questionId);
            const optionsList = document.getElementById(`options-${questionId}`).children;
            const correctionBox = document.getElementById(`correction-${questionId}`);

            for (let i = 0; i < optionsList.length; i++) {
                optionsList[i].disabled = true;
                if (i === question.correct) {
                    optionsList[i].classList.add('correct');
                } else if (i === optionIndex) {
                    optionsList[i].classList.add('incorrect');
                }
            }

            correctionBox.classList.add('show');
            if (optionIndex === question.correct) {
                correctionBox.classList.add('success');
            } else {
                correctionBox.classList.add('error');
            }

            if (Object.keys(userAnswers).length === questions.length) {
                showScore();
            }
        }

