\begin{itemize}[label=\textbullet, itemsep=0.25em, topsep=0.15cm]
    \item $\vec{AB}(-1; 2; -1)$ le vecteur directeur ab ;
    \item $\vec{AC}(1; 1; -2)$ le vecteur directeur ac ;
    \item $\vec{n}(1; 1; 1)$ le vecteur normal potentiel.
\end{itemize}
\vspace{0.45cm}
\noindent\textbf{\large Partie A --- Nature du triangle et plan ABC}
\vspace{0.25cm}
